[
  {
    "statement": "Evidence-based alternatives to prescribed burning for maintaining open grassland habitats for butterflies include adjusting mowing regimes.",
    "citations": [
      "3945"
    ]
  },
  {
    "statement": "Haying supports a higher abundance of prairie specialist butterflies than burning.",
    "citations": [
      "3945"
    ]
  },
  {
    "statement": "For some butterfly species, mowing yields a similar abundance to burning.",
    "citations": [
      "3945"
    ]
  },
  {
    "statement": "Managing species-rich, semi-natural grasslands with grazing and/or mowing is an alternative to prescribed burning.",
    "citations": [
      "3908"
    ]
  },
  {
    "statement": "Butterfly and moth richness and abundance can be similar or higher under light livestock grazing, annual or staggered mowing, or haying compared to burning or unmanaged grassland.",
    "citations": [
      "3908"
    ]
  },
  {
    "statement": "The outcomes of these management strategies on butterfly and moth populations can vary by site and by the specific species involved.",
    "citations": [
      "3908"
    ]
  },
  {
    "statement": "An alternative strategy involves restoring or creating species-rich grassland via scrub clearance and reintroducing grazing or mowing.",
    "citations": [
      "3955"
    ]
  },
  {
    "statement": "Restoring or creating grassland has shown mixed responses in butterfly richness and abundance.",
    "citations": [
      "3955"
    ]
  },
  {
    "statement": "Increased blue-spot hairstreak egg densities have been observed after scrub cutting.",
    "citations": [
      "3955"
    ]
  },
  {
    "statement": "Reducing grazing intensity by seasonal livestock removal is a management strategy for butterflies.",
    "citations": [
      "3960"
    ]
  },
  {
    "statement": "Several studies found higher butterfly and caterpillar abundance where grazing intensity was reduced.",
    "citations": [
      "3960"
    ]
  },
  {
    "statement": "Some research showed that sites with reduced grazing intensity had similar butterfly richness or abundance to continuously grazed sites.",
    "citations": [
      "3960"
    ]
  },
  {
    "statement": "A European review reported that reducing grazing intensity benefits many butterfly species.",
    "citations": [
      "3960"
    ]
  },
  {
    "statement": "Employing rough grazing in semi-natural habitats serves as an alternative management strategy for butterflies.",
    "citations": [
      "3944"
    ]
  },
  {
    "statement": "Rough grazing with cattle, ponies, or light sheep in habitats like dunes, saltmarsh, and shrubsteppe can show similar or higher butterfly and moth richness and abundance than unmanaged land or cutting.",
    "citations": [
      "3944"
    ]
  },
  {
    "statement": "Rough grazing has been shown to increase occupancy for some butterfly species.",
    "citations": [
      "3944"
    ]
  },
  {
    "statement": "Delaying cutting or first grazing dates is a strategy to create sward variation.",
    "citations": [
      "3967"
    ]
  },
  {
    "statement": "Late mowing or later grazing start dates are associated with higher abundance for some butterflies and moths in certain years or contexts.",
    "citations": [
      "3967"
    ]
  }
]

[
  {
    "statement": "Restoring connectivity between habitat patches increased the abundance of butterfly species including the Karner blue, high brown fritillary, small pearl-bordered fritillary, marsh fritillary and regal fritillary.",
    "citations": [
      "3934"
    ]
  },
  {
    "statement": "Butterflies used connected habitats more frequently.",
    "citations": [
      "3934"
    ]
  },
  {
    "statement": "Common buckeye and variegated fritillary butterflies were more likely to move between connected habitat patches.",
    "citations": [
      "3934"
    ]
  },
  {
    "statement": "Grassland strips that provided nectar or shelter were more likely to be used by butterflies than strips with no resources.",
    "citations": [
      "3934"
    ]
  },
  {
    "statement": "Retaining connectivity helped the persistence of butterfly populations in suboptimal sites.",
    "citations": [
      "3832"
    ]
  },
  {
    "statement": "Low-quality habitat patches that were well connected were more likely to retain Alcon large blue populations than less connected patches.",
    "citations": [
      "3832"
    ]
  },
  {
    "statement": "Habitat corridors facilitated the colonization of butterflies over longer distances.",
    "citations": [
      "3832"
    ]
  },
  {
    "statement": "Common buckeye butterflies were more likely to colonize farther-away patches when released on suitable habitat corridors than when released in unsuitable habitat.",
    "citations": [
      "3832"
    ]
  }
]

[
  {
    "statement": "Reducing or eliminating fertilizers, pesticides, or herbicides on farmland was associated with higher species richness and abundance of butterflies, moths, or their caterpillars.",
    "citations": []
  },
  {
    "statement": "Some studies reported that the species richness and abundance of butterflies and moths were similar in contexts with reduced chemical inputs compared to conventional applications.",
    "citations": [
      "3897",
      "3919"
    ]
  },
  {
    "statement": "Studies reported greater species richness in orchards, crop edges, farms, vineyards, replanted forest stands, coffee plantations, and agricultural landscapes with reduced or no chemical inputs.",
    "citations": [
      "3897"
    ]
  },
  {
    "statement": "A higher richness of specialist moths was found on unfertilized grassland.",
    "citations": [
      "3897"
    ]
  },
  {
    "statement": "Some sites with reduced chemical inputs showed similar species richness to sites under conventional management.",
    "citations": [
      "3897"
    ]
  },
  {
    "statement": "On permanent grasslands, lower-input management and stopping chemical applications were linked to higher species richness of butterflies and moths.",
    "citations": [
      "3958"
    ]
  },
  {
    "statement": "On permanent grasslands, lower-input management and stopping chemical applications were linked to more specialist moths and more species of conservation concern.",
    "citations": [
      "3958"
    ]
  },
  {
    "statement": "Large moth species richness increased on permanent grasslands after grazing was reduced and chemicals were stopped.",
    "citations": [
      "3958"
    ]
  },
  {
    "statement": "The abundance of adult butterflies, moths, and caterpillars was higher under reduced or no chemical inputs in several settings.",
    "citations": [
      "3897"
    ]
  },
  {
    "statement": "On low-input or unfertilized, ungrazed grasslands managed with a single cut, the abundance of butterflies, micro-moths, and declining macro-moths was higher than on intensively managed grassland.",
    "citations": [
      "3958"
    ]
  },
  {
    "statement": "After reducing grazing and stopping chemicals on grasslands, the total abundance of large moths and several butterfly species increased.",
    "citations": [
      "3958"
    ]
  },
  {
    "statement": "In Spanish vineyards, fewer chemical inputs were linked to greater butterfly species richness.",
    "citations": [
      "3919"
    ]
  },
  {
    "statement": "In USA vineyards, fewer chemical inputs were linked to greater butterfly abundance.",
    "citations": [
      "3919"
    ]
  },
  {
    "statement": "In orchards, unmanaged or partially managed sites had higher richness and diversity of leaf-eating arthropods, including caterpillars, than commercially managed sites.",
    "citations": [
      "3917"
    ]
  },
  {
    "statement": "Managed orchards had a lower abundance of butterflies and burnet moths than abandoned orchards.",
    "citations": [
      "3917"
    ]
  },
  {
    "statement": "Conversion to organic farming was associated with greater species richness and abundance of butterflies and moths than on conventional farms.",
    "citations": [
      "3907"
    ]
  },
  {
    "statement": "The benefits of organic farming for butterfly and moth populations sometimes varied with the landscape context and the time since conversion.",
    "citations": [
      "3907"
    ]
  },
  {
    "statement": "A study reported increases in large moth abundance and some butterfly species after a farm's conversion to organic practices alongside other management changes.",
    "citations": [
      "3907"
    ]
  }
]

[
  {
    "statement": "Thinning trees is an evidence-based, non-burning disturbance option in forests.",
    "citations": [
      "3940"
    ]
  },
  {
    "statement": "Studies reported higher butterfly richness and/or abundance one to four years after thinning trees compared to unmanaged woodland.",
    "citations": [
      "3940"
    ]
  },
  {
    "statement": "One study found thinned forest had similar butterfly richness and abundance to unmanaged woodland.",
    "citations": [
      "3940"
    ]
  },
  {
    "statement": "Rarer fruit-feeding butterfly species were less frequent in thinned forest.",
    "citations": [
      "3940"
    ]
  },
  {
    "statement": "Partially-cleared plots had higher butterfly richness but lower moth richness than closed-canopy forest.",
    "citations": [
      "3940"
    ]
  },
  {
    "statement": "Coppicing woodland is an evidence-based, non-burning disturbance option in forests.",
    "citations": [
      "3939"
    ]
  },
  {
    "statement": "Multiple studies found a higher abundance of butterflies generally, and of species such as the heath fritillary, in recently coppiced stands.",
    "citations": [
      "3939"
    ]
  },
  {
    "statement": "The age of a coppiced stand influenced butterfly communities and richness.",
    "citations": [
      "3939"
    ]
  },
  {
    "statement": "Some studies reported lower macro-moth richness and abundance in coppiced stands than in mature forest.",
    "citations": [
      "3939"
    ]
  },
  {
    "statement": "Fritillary butterfly populations were more likely to persist for up to 20 years in coppiced or young-plantation woodlands.",
    "citations": [
      "3939"
    ]
  },
  {
    "statement": "Butterfly abundance also increased after coppicing was combined with scrub control, felling, and grazing.",
    "citations": [
      "3939"
    ]
  },
  {
    "statement": "Clearing or opening patches in forests, including widening rides, is an evidence-based, non-burning disturbance option.",
    "citations": [
      "3938"
    ]
  },
  {
    "statement": "Cleared patches in forests often had greater butterfly richness and abundance than unmanaged or closed-canopy forest.",
    "citations": [
      "3938"
    ]
  },
  {
    "statement": "Larger cleared patches performed better for increasing butterfly richness and abundance.",
    "citations": [
      "3938"
    ]
  },
  {
    "statement": "Clearing patches showed benefits for species such as the chequered blue, woodland brown, high brown fritillary, and small pearl-bordered fritillary.",
    "citations": [
      "3938"
    ]
  },
  {
    "statement": "Some studies noted declines in butterfly populations over the three years following patch clearing.",
    "citations": [
      "3938"
    ]
  },
  {
    "statement": "Some studies noted lower macro-moth abundance in wider forest rides.",
    "citations": [
      "3938"
    ]
  },
  {
    "statement": "A European review reported that opening patches in forests benefits 19 of 67 butterfly species of conservation concern.",
    "citations": [
      "3938"
    ]
  },
  {
    "statement": "Selected pine clearance supported increases and survival of a translocated Baton Blue butterfly population.",
    "citations": [
      "3938"
    ]
  },
  {
    "statement": "Creating young plantations within mature woodland is an evidence-based, non-burning disturbance option in forests.",
    "citations": [
      "3941"
    ]
  },
  {
    "statement": "Larger areas of young plantations or coppicing were associated with higher persistence of pearl-bordered and small pearl-bordered fritillaries over 20 years.",
    "citations": [
      "3941"
    ]
  },
  {
    "statement": "The persistence of these fritillary species was higher in young plantations compared to mature conifer and mature deciduous woodland.",
    "citations": [
      "3941"
    ]
  },
  {
    "statement": "Forest restoration with structural interventions like coppicing, felling, and ride management is an evidence-based, non-burning disturbance option.",
    "citations": [
      "3936"
    ]
  },
  {
    "statement": "After forest restoration, populations of high brown fritillary, pearl-bordered fritillary, wood white, and grizzled skipper butterflies stayed the same or increased.",
    "citations": [
      "3936"
    ]
  },
  {
    "statement": "Butterflies such as the heath fritillary occupied greater areas after forest restoration.",
    "citations": [
      "3936"
    ]
  },
  {
    "statement": "Heath fritillary butterflies were more likely to fly into restored areas than unrestored areas.",
    "citations": [
      "3936"
    ]
  },
  {
    "statement": "The presence of the high brown fritillary was maintained or higher after restoration, with associations to brash and bracken litter coverage.",
    "citations": [
      "3936"
    ]
  },
  {
    "statement": "Reducing planting density to create warmer woodlands has been proposed as a management technique.",
    "citations": [
      "3875"
    ]
  },
  {
    "statement": "No studies were found evaluating the effects of reducing planting density on butterflies or moths.",
    "citations": [
      "3875"
    ]
  }
]

[
  {
    "statement": "The evidence base regarding the effectiveness of agri-environment schemes for butterfly and moth conservation is comprised of 32 studies.",
    "citations": [
      "3915"
    ]
  },
  {
    "statement": "Of the 32 studies, 18 were conducted in the UK, eight in Switzerland, two in Finland, and one each in Sweden, the Czech Republic, and Germany.",
    "citations": [
      "3915"
    ]
  },
  {
    "statement": "Across 15 studies in Switzerland, the UK and Sweden, 12 reported higher butterfly or moth richness or diversity on lands managed under agri-environment schemes than on conventional fields or farms.",
    "citations": [
      "3915"
    ]
  },
  {
    "statement": "Across 15 studies in Switzerland, the UK and Sweden, three studies reported similar butterfly or moth richness on lands managed under agri-environment schemes compared to conventional fields or farms.",
    "citations": [
      "3915"
    ]
  },
  {
    "statement": "In Switzerland, one of two landscape-scale studies found higher butterfly richness in landscapes with a greater proportion of land under agri-environment schemes.",
    "citations": [
      "3915"
    ]
  },
  {
    "statement": "A separate landscape-scale study in Switzerland found similar butterfly richness at the farm scale.",
    "citations": [
      "3915"
    ]
  },
  {
    "statement": "A study in Finland found lower butterfly and moth richness on grassland managed under agri-environment schemes than on abandoned, unmanaged grassland.",
    "citations": [
      "3915"
    ]
  },
  {
    "statement": "Across 19 studies in the UK, Sweden, Switzerland and Germany, 17 reported higher abundance of butterflies or moths on land under agri-environment schemes than in unmanaged or conventional sites.",
    "citations": [
      "3915"
    ]
  },
  {
    "statement": "Across 19 studies in the UK, Sweden, Switzerland and Germany, two studies found similar abundance of butterflies or moths on margins.",
    "citations": [
      "3915"
    ]
  },
  {
    "statement": "Three of four studies conducted in the UK and Switzerland found higher butterfly abundance on farms or in landscapes with a higher proportion of land under agri-environment schemes.",
    "citations": [
      "3915"
    ]
  },
  {
    "statement": "One of four studies conducted in the UK and Switzerland found species-specific mixed responses for butterfly abundance.",
    "citations": [
      "3915"
    ]
  },
  {
    "statement": "Three studies in Finland and the Czech Republic reported lower butterfly and moth abundance on grazed or restored grasslands under agri-environment schemes than on unmanaged grassland.",
    "citations": [
      "3915"
    ]
  },
  {
    "statement": "One case showed a decline in the Danube clouded yellow butterfly after mowing, as part of an agri-environment scheme, began on abandoned grasslands.",
    "citations": [
      "3915"
    ]
  },
  {
    "statement": "There were no studies found regarding the effect of agri-environment schemes on butterfly or moth behaviour.",
    "citations": [
      "3915"
    ]
  },
  {
    "statement": "Undersowing spring cereals as part of an agri-environment scheme showed mixed results for butterfly and moth conservation.",
    "citations": [
      "3926"
    ]
  },
  {
    "statement": "One UK randomized, controlled study found that undersowing spring cereals resulted in higher butterfly richness and abundance but lower caterpillar abundance than on extensively or conventionally managed grassland.",
    "citations": [
      "3926"
    ]
  },
  {
    "statement": "A Swiss site comparison found similar butterfly richness and abundance on farms with more in-field agri-environment scheme options compared to farms with fewer such options.",
    "citations": [
      "3926"
    ]
  }
]

[
  {
    "statement": "In Germany, managed and abandoned traditional orchards were found to have similar species richness of butterflies and burnet moths.",
    "citations": [
      "3917"
    ]
  },
  {
    "statement": "In Germany, managed and abandoned traditional orchards were found to have a similar community composition of butterflies and burnet moths.",
    "citations": [
      "3917"
    ]
  },
  {
    "statement": "Managed traditional orchards in Germany had a lower abundance of butterflies and burnet moths compared to abandoned orchards.",
    "citations": [
      "3917"
    ]
  },
  {
    "statement": "In the USA, unmanaged and partially managed orchards had greater species richness of leaf-eating arthropods, including caterpillars, than commercially managed orchards.",
    "citations": [
      "3917"
    ]
  },
  {
    "statement": "In the USA, unmanaged and partially managed orchards had greater diversity of leaf-eating arthropods, including caterpillars, than commercially managed orchards.",
    "citations": [
      "3917"
    ]
  },
  {
    "statement": "In the USA, vineyards managed to encourage native plants with rare insecticide use had greater butterfly abundance than conventionally managed vineyards.",
    "citations": [
      "3919"
    ]
  },
  {
    "statement": "In the USA, grass strips between vine rows and reduced chemical use were associated with greater butterfly species richness than vine rows and conventional management.",
    "citations": [
      "3919"
    ]
  }
]

[
  {
    "statement": "In studies of grazing management on grasslands, lowering stocking density was associated with higher butterfly and moth species richness in five of eight replicated studies.",
    "citations": [
      "3959"
    ]
  },
  {
    "statement": "The studies on grazing management were conducted across the UK, Sweden, Germany, the USA, and Switzerland.",
    "citations": [
      "3959"
    ]
  },
  {
    "statement": "Two of the eight studies found no difference in species richness, and one study found lower richness at low stocking density in one year.",
    "citations": [
      "3959"
    ]
  },
  {
    "statement": "The seasonal removal of livestock showed mixed effects on butterfly richness.",
    "citations": [
      "3960"
    ]
  },
  {
    "statement": "In two of three replicated, controlled UK studies, fields where cattle were removed in summer or not grazed in September had similar butterfly richness compared to continuously grazed fields.",
    "citations": [
      "3960"
    ]
  },
  {
    "statement": "One of the three replicated, controlled UK studies found greater butterfly richness when cattle were removed in summer.",
    "citations": [
      "3960"
    ]
  },
  {
    "statement": "Rotational grazing produced variable outcomes for butterfly and burnet moth richness.",
    "citations": [
      "3965"
    ]
  },
  {
    "statement": "Among four replicated studies in France and the USA, two found higher butterfly and burnet moth richness under rotational grazing with cattle or sheep than under continuous or patch-burn treatments.",
    "citations": [
      "3965"
    ]
  },
  {
    "statement": "One replicated study found no difference in richness under rotational sheep grazing.",
    "citations": [
      "3965"
    ]
  },
  {
    "statement": "One replicated study found higher richness only under rotational cattle grazing at a high stocking density, but not at a low stocking density.",
    "citations": [
      "3965"
    ]
  },
  {
    "statement": "An additional site comparison in the USA linked a longer time since rotational management was implemented with higher richness.",
    "citations": [
      "3965"
    ]
  }
]

[
  {
    "statement": "Evidence reports that butterfly community responses to grassland management changes span from weeks to decades.",
    "citations": [
      "3956",
      "3945",
      "3971",
      "3957"
    ]
  },
  {
    "statement": "After grazing ceased, a study detected changes within two weeks, observing lower butterfly abundance than in grazed areas.",
    "citations": [
      "3956"
    ]
  },
  {
    "statement": "Following management by haying, the abundance of prairie specialist butterflies differed between the first and second year after the haying occurred.",
    "citations": [
      "3945"
    ]
  },
  {
    "statement": "After restoration actions like tree and shrub removal in wet meadows, marsh fritillary caterpillar webs increased the following year.",
    "citations": [
      "3971"
    ]
  },
  {
    "statement": "Over a period of one to six years after the abandonment of mowing and grazing, the butterfly community shifted toward generalist species.",
    "citations": [
      "3957",
      "3956"
    ]
  },
  {
    "statement": "Over a period of one to six years after the abandonment of mowing and grazing, the butterfly community shifted toward species with fewer generations per year.",
    "citations": [
      "3957",
      "3956"
    ]
  },
  {
    "statement": "Species- or group-specific butterfly responses were reported around six years after the abandonment of management practices.",
    "citations": [
      "3957"
    ]
  },
  {
    "statement": "Around six years after abandonment, heath fritillary abundance was similar to the abundance found in annually mown sites.",
    "citations": [
      "3957"
    ]
  },
  {
    "statement": "In areas abandoned for more than 25 years, there were lower numbers of adult butterflies and no caterpillars.",
    "citations": [
      "3957"
    ]
  },
  {
    "statement": "Comparative studies assessed butterfly communities and populations across timeframes of 3–13, 5–15, 5–20, and more than 10 years since abandonment.",
    "citations": [
      "3957",
      "3956"
    ]
  },
  {
    "statement": "These comparative studies showed differing butterfly richness and abundance patterns depending on the duration of abandonment and the specific taxa.",
    "citations": [
      "3957",
      "3956"
    ]
  },
  {
    "statement": "Butterfly density was higher where grazing had ceased for 2 to 9 years compared to sites abandoned for more than 10 years or sites that were still grazed.",
    "citations": [
      "3956"
    ]
  },
  {
    "statement": "Very long-term comparisons recorded lower butterfly species richness in sites abandoned for over 50 years than in more recently mown sites.",
    "citations": [
      "3957"
    ]
  }
]

[
  {
    "statement": "No studies were found evaluating the effects on butterflies and moths of requiring Environmental Impact Assessments for developers.",
    "citations": [
      "3840"
    ]
  },
  {
    "statement": "No studies were found evaluating the effects on butterflies and moths of using glazing treatments to reduce light spill from buildings.",
    "citations": [
      "3905"
    ]
  },
  {
    "statement": "Fewer moths and moth species were attracted to yellow, green, white, or red lights than to UV, actinic, blue, or conventional metal halide lights.",
    "citations": [
      "3906"
    ]
  },
  {
    "statement": "One study found four moth species fed longer under red lights than under white or green lights.",
    "citations": [
      "3906"
    ]
  },
  {
    "statement": "The same four moth species fed for less time under red lights than they did in darkness.",
    "citations": [
      "3906"
    ]
  },
  {
    "statement": "A replicated site comparison study found that gardens without insecticides and herbicides had higher butterfly abundance.",
    "citations": [
      "3900"
    ]
  },
  {
    "statement": "A replicated site comparison study found that gardens without fungicides and snail pellets had lower butterfly abundance.",
    "citations": [
      "3900"
    ]
  },
  {
    "statement": "Less frequently mown or unmown urban greenspaces had higher butterfly and moth species richness and diversity.",
    "citations": [
      "3841"
    ]
  },
  {
    "statement": "Unmown parks and verges had higher butterfly abundance.",
    "citations": [
      "3841"
    ]
  },
  {
    "statement": "Roadsides mown in late summer had more ringlet butterflies.",
    "citations": [
      "3841"
    ]
  },
  {
    "statement": "Less frequent or later mowing reduced butterfly roadkill.",
    "citations": [
      "3841"
    ]
  },
  {
    "statement": "Butterflies occurred more often on less frequently mown urban grasslands.",
    "citations": [
      "3841"
    ]
  },
  {
    "statement": "On mowed verges, butterflies were only recorded where hay was removed.",
    "citations": [
      "3841"
    ]
  },
  {
    "statement": "Maintaining species-rich, semi-natural grassland with extensive grazing or appropriate mowing generally had positive effects for some butterflies and moths compared to abandonment or intensive management.",
    "citations": [
      "3908"
    ]
  },
  {
    "statement": "Semi-natural grasslands often supported a higher abundance of butterflies than conventional crops.",
    "citations": [
      "3908"
    ]
  },
  {
    "statement": "Disking to create bare ground increased the abundance of disturbance-tolerant butterflies but did not increase the richness of grassland butterfly species.",
    "citations": [
      "3935"
    ]
  },
  {
    "statement": "Occupancy by the Alcon large blue butterfly was similar between sod-cut and unmanaged heathlands.",
    "citations": [
      "3935"
    ]
  },
  {
    "statement": "Occupancy by the Alcon large blue butterfly was less likely where sod cutting and grazing were combined.",
    "citations": [
      "3935"
    ]
  },
  {
    "statement": "A stripped sand dune plot supported a translocated belted beauty moth population, while a strimmed and raked plot did not.",
    "citations": [
      "3935"
    ]
  },
  {
    "statement": "Some created bare-ground plots were used by certain moth species two to three years after creation.",
    "citations": [
      "3935"
    ]
  }
]

[
  {
